states.bc1169cd4344:
{
 "call_meta": {
  "company": "Meridale Health Group",
  "event": "Q1 2026 earnings call",
  "date": "2026-04-16"
 },
 "outlook_table": {
  "adjusted_eps_prior_jan_2026": "$21.20 to $21.70",
  "adjusted_eps_revised": "$19.00 to $19.50",
  "medical_care_ratio_prior": "86.0% +/- 50 bps",
  "medical_care_ratio_revised": "87.5% +/- 50 bps",
  "cash_flow_from_operations": "greater than 1.1x net income (unchanged)"
 },
 "ceo_prepared": "This is the first time in sixteen years that we have lowered our annual earnings outlook, and I want to be direct about why. Care activity among our Medicare Advantage members accelerated in the quarter well beyond what we had priced into our 2026 bids. We set those bids last spring, before the trend was visible, and that is on us. Our pharmacy benefits business performed in line with plan, and we are not changing our long-term growth targets.",
 "cfo_prepared": "Roughly two-thirds of the pressure comes from higher utilization of outpatient and physician services among existing Medicare Advantage members. About one-third comes from members who joined us after other plans exited their markets; their care needs are running higher than we assumed. The revised outlook assumes the elevated trend we saw in the first quarter persists for the rest of the year, with no improvement. We will reflect these trends fully in our 2027 bids, which are due in June.",
 "qa": [
  {
   "speaker": "Analyst — Callum Ferreira-Nakamura, Wexford Partners",
   "text": "So you're basically telling us margin recovery in 2027 is off the table?"
  },
  {
   "speaker": "CFO — Beatrix Oduya",
   "text": "No, I didn't say that. Repricing benefits and bids for 2027 is exactly how we start that recovery. What I said is we won't assume any improvement in 2026."
  },
  {
   "speaker": "Analyst — Hana Kowalczyk, Fairmont Rowe",
   "text": "Is there anything unusual in the quarter, like one-time costs, that inflates the trend?"
  },
  {
   "speaker": "CFO — Beatrix Oduya",
   "text": "Nothing material. We did have a small prior-period reserve release, under $40 million, which actually flatters the quarter slightly."
  }
 ],
 "safe_harbor": "Forward-looking statements are subject to risks including medical cost trends, government program funding and rates, and the factors in our Form 10-K."
}
